const tones = new Map();
const kit = {
  register(name, tone) {
    tones.set(name, tone(kit));
  },
  paint(text, options) {
    const tone = tones.get(options.tone);
    if (tone === undefined) throw new Error(`unknown tone '${options.tone}'`);
    return { value: tone.open + text + tone.close, tone: options.tone, length: text.length };
  },
  has(name) {
    return tones.has(name);
  },
  list() {
    return [...tones.keys()];
  },
};
export default kit;
// Members the package's own declarations leave out.
kit.count = () => tones.size;
kit.clear = () => {
  tones.clear();
};
